const res = $input.first().json;
const rowCount = (res.data && res.data.rows && res.data.rows[0]) ? res.data.rows[0][0] : 0;
const isHealthy = rowCount > 0;

return [{
  json: {
    environment: 'PRODUCTION',
    timestamp: new Date().toISOString(),
    rowCount: rowCount,
    isHealthy: isHealthy,
    message: isHealthy 
      ? `✅ [TimescaleDB MDDS PROD] Dữ liệu Ticks V3 hôm nay ổn định: ${rowCount} records.` 
      : `🚨 [TimescaleDB MDDS PROD CẢNH BÁO] Không tìm thấy dữ liệu Ticks V3 cho phiên hôm nay!`
  }
}];

const input = $input.first();
const fields = (input && input.json && input.json.fields) ? input.json.fields : {};

// Bóc tách text đơn giản từ description (bỏ ADF rườm rà)
let cleanDesc = '';
if (fields.description && fields.description.content) {
  cleanDesc = JSON.stringify(fields.description.content);
} else if (typeof fields.description === 'string') {
  cleanDesc = fields.description;
}

// Lấy thêm các tham chiếu quan trọng (References)
const attachments = fields.attachment ? fields.attachment.map(a => ({ filename: a.filename, size: a.size, content: a.content })) : [];
const issueLinks = fields.issuelinks ? fields.issuelinks.map(l => l.outwardIssue ? l.outwardIssue.key : (l.inwardIssue ? l.inwardIssue.key : null)).filter(Boolean) : [];

// Trả về payload cực gọn cho Agent suy luận
return [{
  json: {
    issueKey: $node['Webhook Agent'].json.body.issueKey || '',
    summary: fields.summary || '',
    status: fields.status ? fields.status.name : 'Unknown',
    assignee: fields.assignee ? fields.assignee.displayName : 'Unassigned',
    reporter: fields.reporter ? fields.reporter.displayName : 'Unknown',
    labels: fields.labels || [],
    attachments: attachments,
    issueLinks: issueLinks,
    descriptionSnippet: cleanDesc.substring(0, 1500)
  }
}];

