try {
  const response = $input.first().json;
  const rawText = response.candidates?.[0]?.content?.parts?.[0]?.text || '';
  // Handle: JSON thuần, markdown code block, hoặc Antigravity trả nested object
  let data;
  if (typeof rawText === 'object') {
    data = rawText;
  } else {
    const cleanJson = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    data = JSON.parse(cleanJson);
  }
  // Validate intent hợp lệ
  const validIntents = ['standup', 'test', 'jira', 'squash', 'sync', 'help'];
  if (!validIntents.includes(data.intent)) data.intent = 'help';
  return [{ json: data }];
} catch(e) {
  return [{ json: { intent: 'help', error: e.message } }];
}

